-- Name: geo_subdistrict; Type: TABLE; Schema: public; Owner: -

CREATE TABLE public.geo_subdistrict (
    id integer NOT NULL,
    name_th text,
    district_th text,
    province_th text,
    region_th text,
    cen_lon double precision,
    cen_lat double precision,
    geom public.geometry(MultiPolygon,4326)
);

CREATE SEQUENCE public.geo_subdistrict_id_seq AS integer START WITH 1 INCREMENT BY 1 NO MINVALUE NO MAXVALUE CACHE 1;

ALTER SEQUENCE public.geo_subdistrict_id_seq OWNED BY public.geo_subdistrict.id;

ALTER TABLE ONLY public.geo_subdistrict ALTER COLUMN id SET DEFAULT nextval('public.geo_subdistrict_id_seq'::regclass);


SELECT pg_catalog.setval('public.geo_subdistrict_id_seq', 7630, true);

ALTER TABLE ONLY public.geo_subdistrict
    ADD CONSTRAINT geo_subdistrict_pkey PRIMARY KEY (id);

CREATE INDEX geo_subdistrict_geom_idx ON public.geo_subdistrict USING gist (geom);
CREATE INDEX geo_subdistrict_province_th_idx ON public.geo_subdistrict (province_th);
